<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Controller;
use App\Core\HttpError;
final class AuthController extends Controller {
 public function login():void{if($_SERVER['REQUEST_METHOD']==='POST'){$this->post();$email=strtolower($this->text('email',3,190));$password=$this->text('password',1,128);$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$n=(int)$this->store->run('SELECT COUNT(*) FROM auth_attempts WHERE ip_hash=? AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)',[$ip])->fetchColumn();if($n>=10)throw new HttpError(429,'Juda ko‘p urinish. 15 daqiqadan so‘ng qayta urinib ko‘ring.');$u=$this->store->run('SELECT * FROM users WHERE email=?',[$email])->fetch();if(!$u||!password_verify($password,$u['password_hash'])){$this->store->run('INSERT INTO auth_attempts(ip_hash) VALUES(?)',[$ip]);throw new HttpError(422,'Email yoki parol noto‘g‘ri.');}session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));flash('Tizimga kirdingiz.');redirect();}$this->view('auth',['title'=>'Kirish','mode'=>'login']);}
 public function register():void{if($_SERVER['REQUEST_METHOD']==='POST'){$this->post();$name=$this->text('name',2,80);$email=strtolower($this->text('email',3,190));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new HttpError(422,'Email manzili noto‘g‘ri.');$p=$this->text('password',8,72);if(!preg_match('/[A-Za-z]/',$p)||!preg_match('/[0-9]/',$p))throw new HttpError(422,'Parolda harf va raqam bo‘lsin.');if($this->store->run('SELECT id FROM users WHERE email=?',[$email])->fetch())throw new HttpError(422,'Ushbu email ro‘yxatdan o‘tgan.');$this->store->run('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"user")',[$name,$email,password_hash($p,PASSWORD_DEFAULT)]);flash('Hisob yaratildi. Endi tizimga kiring.');redirect('login');}$this->view('auth',['title'=>'Hisob yaratish','mode'=>'register']);}
 public function logout():void{$this->post();$this->auth();$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-3600,$p['path'],$p['domain'],$p['secure'],$p['httponly']);}session_destroy();redirect('login');}
 public function users():void{$this->auth(['admin']);$this->view('users',['title'=>'Hisoblar va rollar','items'=>$this->store->run('SELECT id,name,email,role FROM users ORDER BY id')->fetchAll()]);}
 public function role():void{$this->post();$u=$this->auth(['admin']);$id=$this->id('id',true);$role=$_POST['role']??'';if(!in_array($role,['admin','moderator','user'],true))throw new HttpError(422,'Rol noto‘g‘ri.');if((int)$u['id']===$id)throw new HttpError(409,'O‘z rolingizni o‘zgartira olmaysiz.');if(!$this->store->find('users',$id))throw new HttpError(404,'Hisob topilmadi.');$this->store->run('UPDATE users SET role=? WHERE id=?',[$role,$id]);flash('Rol yangilandi.');redirect('users');}
}
